@RunWith(MockitoJUnitRunner.class)
public class FastDateFormat_applyRules_TriageGen2Test {

    /**
     * Since applyRules is protected and mRules is a private field, 
     * we use reflection to inject mock rules and invoke the method.
     */
    @Test
    public void testApplyRules_Success() throws Exception {
        // Setup
        String pattern = "yyyy-MM-dd";
        FastDateFormat fdf = FastDateFormat.getInstance(pattern);

        Calendar calendar = Calendar.getInstance();
        StringBuffer buf = new StringBuffer("Prefix: ");

        // Mock Rule array
        Rule rule1 = mock(Rule.class);
        Rule rule2 = mock(Rule.class);
        Rule[] rules = new Rule[]{rule1, rule2};

        // Inject rules via reflection
        Field rulesField = FastDateFormat.class.getDeclaredField("mRules");
        rulesField.setAccessible(true);
        rulesField.set(fdf, rules);

        // Define behavior: rule1 appends "A", rule2 appends "B"
        doAnswer(invocation -> {
            StringBuffer b = invocation.getArgument(0);
            Calendar c = invocation.getArgument(1);
            b.append("A");
            return null;
        }).when(rule1).appendTo(any(StringBuffer.class), any(Calendar.class));

        doAnswer(invocation -> {
            StringBuffer b = invocation.getArgument(0);
            Calendar c = invocation.getArgument(1);
            b.append("B");
            return null;
        }).when(rule2).appendTo(any(StringBuffer.class), any(Calendar.class));

        // Execute
        // Accessing protected method via reflection
        java.lang.reflect.Method applyRulesMethod = FastDateFormat.class.getDeclaredMethod("applyRules", Calendar.class, StringBuffer.class);
        applyRulesMethod.setAccessible(true);
        StringBuffer result = (StringBuffer) applyRulesMethod.invoke(fdf, calendar, buf);

        // Verify
        assertEquals("Prefix: AB", result.toString());
        assertSame(buf, result);
        verify(rule1, times(1)).appendTo(buf, calendar);
        verify(rule2, times(1)).appendTo(buf, calendar);
    }

    @Test
    public void testApplyRules_EmptyRules() throws Exception {
        // Setup
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy");
        Calendar calendar = Calendar.getInstance();
        StringBuffer buf = new StringBuffer("Start");

        // Inject empty rules array
        Field rulesField = FastDateFormat.class.getDeclaredField("mRules");
        rulesField.setAccessible(true);
        rulesField.set(fdf, new Rule[0]);

        // Execute
        java.lang.reflect.Method applyRulesMethod = FastDateFormat.class.getDeclaredMethod("applyRules", Calendar.class, StringBuffer.class);
        applyRulesMethod.setAccessible(true);
        StringBuffer result = (StringBuffer) applyRulesMethod.invoke(fdf, calendar, buf);

        // Verify
        assertEquals("Start", result.toString());
        assertSame(buf, result);
    }

    @Test(expected = Exception.class)
    public void testApplyRules_NullRulesThrowsException() throws Exception {
        // Setup
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy");
        Calendar calendar = Calendar.getInstance();
        StringBuffer buf = new StringBuffer();

        // Inject null rules
        Field rulesField = FastDateFormat.class.getDeclaredField("mRules");
        rulesField.setAccessible(true);
        rulesField.set(fdf, null);

        // Execute
        java.lang.reflect.Method applyRulesMethod = FastDateFormat.class.getDeclaredMethod("applyRules", Calendar.class, StringBuffer.class);
        applyRulesMethod.setAccessible(true);
        applyRulesMethod.invoke(fdf, calendar, buf);

        // Verify: Should throw NullPointerException due to mRules.length
    }
}
